function load(){try{return {...structuredClone(defaultState),...JSON.parse(localStorage.getItem(DB_KEY)||"{}"),user:null,users:[]} }catch{return structuredClone(defaultState)}}
function save(){localStorage.setItem(DB_KEY,JSON.stringify({...state,user:null,users:[]}))}
function toast(msg){const e=$("#toast");e.textContent=msg;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2400)}
function activity(type,description,sessionName=""){state.activities.unshift({id:uid(),type,description,sessionName,createdAt:now(),owner:state.user?.id});save()}
function mine(list){return state.user?.role==="admin"?list:list.filter(x=>x.owner===state.user?.id)}
function download(name,text,type="text/plain"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function route(){return location.hash.replace(/^#\/?/,"")|| (state.user?"dashboard":"home")}
function go(path){location.hash=`#/${path}`}

