function authPage(kind){const reg=kind==="register";return `<div class="auth-wrap"><form class="card auth-card" id="auth-form"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><h1>${reg?"Criar conta":"Bem-vindo de volta"}</h1><p class="muted">${reg?"Cadastre-se para iniciar sua revisão.":"Entre com sua conta segura."}</p><button type="button" class="btn btn-google" id="google-login"><span class="google-mark" aria-hidden="true">G</span>Continuar com Google</button><div class="auth-divider"><span>ou use seu e-mail</span></div>${reg?`<div class="field"><label>Nome</label><input name="name" required autocomplete="name"></div>`:""}<div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Senha</label><input name="password" type="password" minlength="8" required autocomplete="${reg?"new-password":"current-password"}"></div>${reg?`<div class="field"><label>Instituição</label><input name="institution" value="PPGCN/UERN" autocomplete="organization"></div>`:""}<button type="submit" class="btn btn-primary" style="width:100%">${reg?"Criar conta":"Entrar"}</button><p class="auth-switch">${reg?`Já possui uma conta? <a href="#/login">Entrar</a>`:`Ainda não possui uma conta? <a href="#/register">Criar conta</a>`}</p><button type="button" class="btn btn-outline" style="width:100%;margin-top:8px" data-go="home">Voltar</button></form></div>`}

function shell(content){const r=route();return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="icons/icon.svg" alt=""><span>EcoMétrica</span></div><nav>${nav.filter(x=>x[0]!=="admin"||state.user.role==="admin").map(([p,l,i])=>`<a href="#/${p}" class="nav-link ${r.startsWith(p)?"active":""}"><span>${i}</span> ${l}</a>`).join("")}</nav><div class="sidebar-foot">PPGCN/UERN<br>Dados armazenados neste dispositivo</div></aside><section class="app-main"><header class="topbar"><button class="menu-toggle" id="menu-toggle" aria-label="Abrir menu">☰</button><div class="muted">Revisão sistemática · RN · 2004–2025</div><div class="user-chip"><span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span><span class="user-text"><b>${esc(state.user.name)}</b><br><small>${state.user.role==="admin"?"Administrador":"Pesquisador"}</small></span><button class="btn btn-outline btn-sm" id="logout">Sair</button></div></header><main class="content">${content}</main>${appFooter()}</section></div>`}
