function dashboard(){const sessions=mine(state.sessions), articles=mine(state.articles), decisions=mine(state.screeningDecisions), occ=mine(state.occurrences);const screened=decisions.filter(x=>x.decision!=="pending").length,total=decisions.length,progress=total?Math.round(screened/total*100):0;return `${head("Dashboard","Visão geral da revisão sistemática sobre espécies exóticas invasoras na Caatinga.")}<section class="grid metrics"><article class="card metric"><small>Sessões de análise</small><div class="value">${sessions.length}</div></article><article class="card metric"><small>Artigos no corpus</small><div class="value">${articles.filter(x=>!x.isDuplicate).length}</div></article><article class="card metric"><small>Artigos triados</small><div class="value">${screened}</div></article><article class="card metric"><small>Ocorrências GBIF</small><div class="value">${occ.length}</div></article></section><section class="grid two-col" style="margin-top:16px"><article class="card"><h2>Progresso da triagem</h2><div class="progress"><span style="width:${progress}%"></span></div><p><b>${progress}%</b> · ${screened} de ${total||0} registros avaliados</p>${sessions.length?`<button class="btn btn-primary" data-go="sessions">Ver sessões</button>`:`<div class="notice">Crie sua primeira sessão importando um corpus bibliográfico.</div><button class="btn btn-primary" data-go="corpus" style="margin-top:12px">Importar corpus</button>`}</article><article class="card"><h2>Atividades recentes</h2>${mine(state.activities).slice(0,6).map(a=>`<p><b>${esc(a.description)}</b><br><small class="muted">${new Date(a.createdAt).toLocaleString("pt-BR")}</small></p>`).join("")||`<p class="muted">Nenhuma atividade registrada.</p>`}</article></section>`}

